# owner: platform
from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed


def _check_owner(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark belongs to {mark.student_id}"
            )


def _describe(student, missed):
    count = len(missed)
    label = "day" if count == 1 else "days"
    dates = ", ".join(item.isoformat() for item in missed)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {count} {label}: {dates}."


# ---
def build_notice(student: Student, marks: Iterable[Mark]):
    """Short parent notice listing the absent days."""
    marks = list(marks)
    _check_owner(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ProjectError("no absences to report")
    return _describe(student, missed)
